import { ThemedText } from '@/components/themed-text';
import { AppColors, AppRadii, AppSpacing, AppType } from '@/constants/design-tokens';
import LICENSES from '@/constants/open-source-licenses.json';
import { Ionicons } from '@expo/vector-icons';
import React, { useState } from 'react';
import { FlatList, Linking, Platform, Pressable, StyleSheet, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { FrostedScreen, withTopInset } from '@/components/ui/frosted-screen';
import { t } from '@/i18n';

// Generated by scripts/generate-licenses.js from what ships inside the app.
type Package = (typeof LICENSES.packages)[number];

const MONO = Platform.select({ ios: 'Menlo', android: 'monospace', default: 'monospace' });

export default function LicensesScreen() {
  const insets = useSafeAreaInsets();
  const [open, setOpen] = useState<string | null>(null);

  return (
    <FrostedScreen style={styles.screen}>
      <FlatList
        data={LICENSES.packages}
        keyExtractor={item => `${item.name}@${item.version}`}
        contentContainerStyle={withTopInset(styles.page, insets.top)}
        showsVerticalScrollIndicator={false}
        initialNumToRender={20}
        ListHeaderComponent={
          <View style={styles.header}>
            <ThemedText style={styles.eyebrow}>{t('common.configuraciones')}</ThemedText>
            <ThemedText accessibilityRole="header" style={styles.title}>{t('licenses.licenciasDeCodigoAbierto')}</ThemedText>
            <ThemedText style={styles.intro}>
              {t('licenses.hanetEstaHechaConPackagescount', { packagesCount: LICENSES.packages.length })}
            </ThemedText>
          </View>
        }
        ItemSeparatorComponent={Separator}
        renderItem={({ item }) => {
          const key = `${item.name}@${item.version}`;
          return <PackageRow item={item} expanded={open === key} onToggle={() => setOpen(current => (current === key ? null : key))} />;
        }}
      />
    </FrostedScreen>
  );
}

function PackageRow({ item, expanded, onToggle }: { item: Package; expanded: boolean; onToggle: () => void }) {
  const text = item.text == null ? null : LICENSES.texts[item.text];
  return (
    <View style={styles.row}>
      <Pressable
        accessibilityRole="button"
        accessibilityLabel={t('licenses.nameVersionVersionLicenciaLicense', { name: item.name, version: item.version, license: item.license })}
        accessibilityState={{ expanded }}
        accessibilityHint={expanded ? t('licenses.ocultaLaLicencia') : t('licenses.muestraLaLicencia')}
        onPress={onToggle}
        style={({ pressed }) => [styles.rowHead, pressed && styles.pressed]}
      >
        <View style={styles.rowCopy}>
          <ThemedText numberOfLines={1} style={styles.name}>{item.name}</ThemedText>
          <ThemedText numberOfLines={1} style={styles.meta}>{item.version} · {item.license}</ThemedText>
        </View>
        <Ionicons name={expanded ? 'chevron-up' : 'chevron-down'} size={18} color={AppColors.textSecondary} />
      </Pressable>
      {expanded && (
        <View style={styles.details}>
          {!!item.url && (
            <Pressable accessibilityRole="link" onPress={() => void Linking.openURL(item.url!)} hitSlop={6}>
              <ThemedText numberOfLines={1} style={styles.link}>{item.url.replace(/^https?:\/\//, '')}</ThemedText>
            </Pressable>
          )}
          {item.standard && <ThemedText style={styles.note}>{t('licenses.elPaqueteNoIncluyeSu', { license: item.license })}</ThemedText>}
          {!!text && <ThemedText selectable style={styles.licenseText}>{text}</ThemedText>}
        </View>
      )}
    </View>
  );
}

function Separator() {
  return <View style={styles.separator} />;
}

const styles = StyleSheet.create({
  screen: { flex: 1, backgroundColor: AppColors.canvas },
  page: { width: '100%', maxWidth: 430, alignSelf: 'center', paddingHorizontal: AppSpacing.lg, paddingBottom: 150 },

  header: { paddingTop: AppSpacing.lg, paddingBottom: AppSpacing.xl, gap: AppSpacing.xs },
  eyebrow: { ...AppType.caption, color: AppColors.textSecondary },
  title: { ...AppType.title1, color: AppColors.textPrimary },
  intro: { ...AppType.footnote, color: AppColors.textSecondary, marginTop: AppSpacing.sm },

  row: { borderRadius: AppRadii.lg, borderCurve: 'continuous', backgroundColor: AppColors.surface, overflow: 'hidden' },
  rowHead: { minHeight: 56, flexDirection: 'row', alignItems: 'center', gap: AppSpacing.md, paddingHorizontal: AppSpacing.lg, paddingVertical: AppSpacing.sm },
  rowCopy: { flex: 1 },
  name: { ...AppType.callout, color: AppColors.textPrimary },
  meta: { ...AppType.caption, color: AppColors.textSecondary },
  details: { gap: AppSpacing.sm, paddingHorizontal: AppSpacing.lg, paddingBottom: AppSpacing.lg },
  link: { ...AppType.caption, color: AppColors.textPrimary, textDecorationLine: 'underline' },
  note: { ...AppType.caption, color: AppColors.textSecondary, opacity: 0.85 },
  licenseText: { fontFamily: MONO, fontSize: 11, lineHeight: 15, color: AppColors.textSecondary },
  separator: { height: AppSpacing.sm },
  pressed: { opacity: 0.72 },
});
